<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {message} from 'ant-design-vue'
import {api,http,errorMessage} from '../../api/http'
import {templates,templatePreview,downloadBlob,stateLabels,type PrintTemplate,type PrintField} from '../../api/printing'
import {useAuthStore} from '../../stores/auth'
import PdfPreview from '../../components/printing/PdfPreview.vue'
const auth=useAuthStore(),router=useRouter(),items=ref<PrintTemplate[]>([]),total=ref(0),page=ref(1),keyword=ref(''),status=ref<string>(),busy=ref(false),error=ref('')
const uploadOpen=ref(false),code=ref(''),title=ref(''),reason=ref(''),file=ref<File|null>(null),fields=ref<PrintField[]>([]),fieldsOpen=ref(false),fieldSearch=ref(''),bindingEnabled=ref(true)
const command=ref<{row:PrintTemplate;action:string}|null>(null),previewOpen=ref(false),blob=ref<Blob|null>(null)
async function load(){busy.value=true;error.value='';try{const p=await templates({page:page.value-1,size:20,keyword:keyword.value,status:status.value});items.value=p.items;total.value=p.total}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(()=>void load())
function openUpload(row?:PrintTemplate){code.value=row?.templateCode??'';title.value=row?.templateName??'';file.value=null;reason.value='';uploadOpen.value=true}
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]??null}
async function upload(){if(!file.value||!file.value.name.toLowerCase().endsWith('.docx')||file.value.size>5*1024*1024){error.value='请选择 5MB 以内的 DOCX 文件';return}const data=new FormData();Object.entries({templateCode:code.value,templateName:title.value,businessType:'INSPECTION_REPORT',reason:reason.value}).forEach(([k,v])=>data.append(k,v));data.append('file',file.value);busy.value=true;try{const row=await api<PrintTemplate>({url:'/printing/templates',method:'POST',data});uploadOpen.value=false;await load();message.success(`已保留原始 DOCX，并新增第 ${row.templateRevision} 版草稿。请先验证 PDF，再按需发布。`)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function act(){if(!command.value)return;const {row,action}=command.value;busy.value=true;try{await api({url:`/printing/templates/${row.id}/${action}`,method:'POST',data:action==='bind'?{businessType:'INSPECTION_REPORT',enabled:bindingEnabled.value,reason:reason.value}:{versionNo:row.versionNo,reason:reason.value}});command.value=null;message.success('操作完成');await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function preview(row:PrintTemplate){try{blob.value=await templatePreview(row.id);previewOpen.value=true}catch(e){error.value=errorMessage(e)}}
async function sample(){try{downloadBlob((await http.get<Blob>('/printing/sample.docx',{responseType:'blob'})).data,'检验报告示例模板.docx')}catch(e){error.value=errorMessage(e)}}
async function showFields(){try{fields.value=(await api<{definitions:PrintField[]}>({url:'/printing/fields',params:{businessType:'INSPECTION_REPORT'}})).definitions;fieldsOpen.value=true}catch(e){error.value=errorMessage(e)}}
const actions:Record<string,string>={validate:'验证并生成预览',publish:'发布模板',deactivate:'停用模板',bind:'绑定检验报告'}
function ask(row:PrintTemplate,action:string){reason.value='';bindingEnabled.value=true;command.value={row,action}}
</script>
<template><!-- UI Template: T1; inherits shared Global UI V2. -->
<section class="admin-page master-page template-page" data-ui-template="T1"><header class="admin-page-header heading"><div><h1>打印模板</h1><p>维护 Word 排版，验证真实 PDF 后发布到业务页面。</p></div><a-space><a-button @click="showFields">可用字段</a-button><a-button @click="sample">下载中文示例</a-button><a-button v-if="auth.can('print:template:manage')" type="primary" @click="router.push('/admin/print-templates/new')">可视化设计新模板</a-button><a-button v-if="auth.can('print:template:manage')" @click="openUpload()">上传已有 DOCX</a-button></a-space></header><a-alert v-if="error" type="error" :message="error" show-icon class="notice"/><a-card><a-space wrap><a-input-search v-model:value="keyword" placeholder="模板名称 / 编码" allow-clear @search="page=1;load()"/><a-select v-model:value="status" placeholder="全部状态" allow-clear style="width:150px" :options="Object.entries(stateLabels).map(([value,label])=>({value,label}))" @change="page=1;load()"/><a-button @click="load">查询</a-button></a-space><a-table :data-source="items" row-key="id" :loading="busy" :pagination="{current:page,total,pageSize:20,showSizeChanger:false,onChange:(p:number)=>{page=p;void load()}}" :scroll="{x:1000}" class="list"><a-table-column title="模板名称" data-index="templateName"/><a-table-column title="编码" data-index="templateCode"/><a-table-column title="版本" data-index="templateRevision"/><a-table-column title="状态"><template #default="{record}"><a-tag>{{stateLabels[record.status]}}</a-tag></template></a-table-column><a-table-column title="业务"><template #default>检验报告</template></a-table-column><a-table-column title="操作" :width="440"><template #default="{record}"><a-space wrap><a-button v-if="auth.can('print:template:manage')" type="link" @click="router.push(`/admin/print-templates/${record.id}/design`)">可视化编辑 / 新版本</a-button><a-button v-if="auth.can('print:template:manage')" type="link" @click="router.push(`/admin/print-templates/${record.id}/edit`)">高级 Word 编辑（可选）</a-button><a-button v-if="auth.can('print:template:manage')&&['DRAFT','VALIDATED'].includes(record.status)" type="link" @click="ask(record,'validate')">验证</a-button><a-button v-if="record.previewHash" type="link" @click="preview(record)">PDF 预览</a-button><a-button v-if="auth.can('print:template:publish')&&record.status==='VALIDATED'" type="link" @click="ask(record,'publish')">发布</a-button><a-button v-if="auth.can('print:template:publish')&&record.status==='PUBLISHED'" type="link" @click="ask(record,'bind')">业务绑定</a-button><a-button v-if="auth.can('print:template:publish')&&record.status==='PUBLISHED'" type="link" danger @click="ask(record,'deactivate')">停用</a-button><a-button v-if="auth.can('print:template:manage')" type="link" @click="openUpload(record)">上传新版本</a-button></a-space></template></a-table-column></a-table></a-card><a-modal v-model:open="uploadOpen" title="上传 Word 模板 / 新版本" :confirm-loading="busy" :ok-button-props="{disabled:!file||!code.trim()||!title.trim()||!reason.trim()}" @ok="upload"><a-form layout="vertical"><a-form-item label="模板编码"><a-input v-model:value="code" :maxlength="60"/></a-form-item><a-form-item label="模板名称"><a-input v-model:value="title" :maxlength="120"/></a-form-item><a-form-item label="Word 文件"><input type="file" accept=".docx" @change="choose"/><p>原文件模式：保留 DOCX 原始 OOXML 表格结构、合并单元格和复杂版式，不自动转换成简化画布。上传后先验证 PDF，已发布版本保持不变。需要改动原版式时可在 Word 中修改后另传新版本；高级在线 Word 编辑为可选服务。</p></a-form-item><a-form-item label="变更原因"><a-textarea v-model:value="reason" :maxlength="500"/></a-form-item></a-form></a-modal><a-modal :open="!!command" :title="command?actions[command.action]:''" :confirm-loading="busy" :ok-button-props="{disabled:!reason.trim()}" @cancel="command=null" @ok="act"><p>{{command?.row.templateName}} · 第 {{command?.row.templateRevision}} 版</p><p v-if="command?.action==='validate'">使用示例数据进行字段校验和服务端 PDF 转换。</p><a-form-item v-if="command?.action==='bind'" label="业务绑定状态"><a-radio-group v-model:value="bindingEnabled"><a-radio :value="true">启用</a-radio><a-radio :value="false">停用绑定</a-radio></a-radio-group></a-form-item><a-form-item label="操作原因"><a-textarea v-model:value="reason" :maxlength="500"/></a-form-item></a-modal><a-modal v-model:open="previewOpen" title="模板 PDF 预览（示例数据）" width="90vw" :footer="null"><PdfPreview :blob="blob" name="模板预览.pdf"/></a-modal><a-drawer v-model:open="fieldsOpen" title="可用中文字段" width="min(520px, 92vw)"><a-input v-model:value="fieldSearch" placeholder="搜索字段名称或说明"/><p>在 Word 编辑器的「MES 中文打印字段」面板点击字段，即可插入当前光标位置。检验项目使用循环表格入口。</p><a-card v-for="field in fields.filter(f=>(f.label+f.description+f.group).includes(fieldSearch))" :key="field.key" size="small" class="field"><strong>{{field.label}}</strong><a-tag>{{field.group}}</a-tag><p>{{field.description}}</p><small>示例：{{field.example}}</small></a-card></a-drawer></section></template>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:20px}h1{font-size:24px;margin:0 0 6px}.heading p,.field p{color:#68758a;margin:0}.notice,.field{margin-bottom:14px}.list{margin-top:20px}.field strong{margin-right:12px}.field small{color:#68758a}</style>
